INSERT INTO classes VALUES('fighter','Fighter','A master of martial combat, skilled with a variety of weapons and armor.',10,'Strength or Dexterity',2,'{"armor": "chain_mail", "weapons": ["shield"], "equipment": ["dungeoneer_pack", "javelin_2"]}','[{"name": "Martial Weapon", "choice_type": "weapon", "options": ["longsword", "greatsword", "rapier"], "max_selections": 1, "is_required": true}, {"name": "Armor", "choice_type": "armor", "options": ["studded leather", "breastplate", "chain mail"], "max_selections": 1, "is_required": true}]',0);
INSERT INTO classes VALUES('barbarian','Barbarian','A fierce warrior of primitive background who can enter a battle rage.',12,'Strength',2,'{}','[]',1);
INSERT INTO classes VALUES('cleric','Cleric','A priestly champion who wields divine magic in service of a higher power.',8,'Wisdom',2,'{}','[]',2);
INSERT INTO classes VALUES('paladin','Paladin','A holy warrior bound to a sacred oath, wielding divine magic.',10,'Strength and Charisma',2,'{}','[]',3);
INSERT INTO classes VALUES('rogue','Rogue','A scoundrel who uses stealth and trickery to overcome obstacles.',8,'Dexterity',4,'{"armor": "leather_armor", "weapons": ["rapier", "shortbow"], "equipment": ["burglar_pack", "thieves_tools"]}','[]',4);
INSERT INTO classes VALUES('warlock','Warlock','A wielder of magic derived from a bargain with an extraplanar entity.',8,'Charisma',2,'{}','[]',5);
INSERT INTO classes VALUES('wizard','Wizard','A scholarly magic-user capable of manipulating the structures of spellcasting.',6,'Intelligence',2,'{}','[]',6);
INSERT INTO backgrounds VALUES('farmer','Farmer','You know the hard work of the farm and field. You understand the cycle of seasons and the patience required to nurture crops and livestock.','["Animal Handling", "Nature"]','[]','["Carpenter''s Tools"]','{"option_a": {"equipment": ["carpenters_tools", "shovel", "common_clothes", "belt_pouch", "backpack", "potion_of_healing", "rations_5"], "gold": 10}, "option_b": {"gold": 50}}','["carpenters_tools", "shovel", "common_clothes", "belt_pouch", "backpack", "potion_of_healing", "rations_5"]',10,'','','Tough',0);
INSERT INTO backgrounds VALUES('soldier','Soldier','You began training for war as soon as you reached adulthood and carry precious few memories of life before you took up arms. Battle is in your blood. The crash of weapons, the stink of blood, the screams of enemies—this is the music that makes your heart race. War has been your life for as long as you care to remember.','["Athletics", "Intimidation"]','[]','["Gaming Set"]','{"option_a": {"equipment": ["spear", "shortbow", "arrows_20", "gaming_set", "healers_kit", "quiver", "travelers_clothes"], "gold": 14}, "option_b": {"gold": 50}}','["spear", "shortbow", "arrows_20", "gaming_set", "healers_kit", "quiver", "travelers_clothes"]',14,'','','Savage Attacker',1);
INSERT INTO backgrounds VALUES('acolyte','Acolyte','You devoted yourself to service in a temple, either nestled in a town or secluded in a sacred grove. There you performed rites in honor of a god or pantheon. You served under a priest and studied religion. Thanks to your priest''s instruction and your own devotion, you gained mastery over your god''s mysteries.','["Insight", "Religion"]','[]','["Calligrapher''s Supplies"]','{"option_a": {"equipment": ["calligraphers_supplies", "prayer_book", "holy_symbol", "parchment_10", "robe"], "gold": 8}, "option_b": {"gold": 50}}','["calligraphers_supplies", "prayer_book", "holy_symbol", "parchment_10", "robe"]',8,'','','Magic Initiate (Cleric)',2);
INSERT INTO backgrounds VALUES('criminal','Criminal','You once broke the law and paid for it, learning a hard lesson about the reach of legal authority. You spent time among other criminals and developed connections within the criminal underworld. You''re far closer than most people to the world of murder, theft, and violence that pervades the underbelly of civilization.','["Sleight of Hand", "Stealth"]','[]','["Thieves'' Tools"]','{"option_a": {"equipment": ["dagger", "dagger", "thieves_tools", "crowbar", "pouch", "pouch", "travelers_clothes"], "gold": 16}, "option_b": {"gold": 50}}','["dagger", "dagger", "thieves_tools", "crowbar", "pouch", "pouch", "travelers_clothes"]',16,'','','Alert',3);
INSERT INTO backgrounds VALUES('sage','Sage','You spent your formative years traveling between libraries, scriptoriums, and universities, learning from scholars, wizards, and other learned persons. You became an apprentice to a master who taught you to value knowledge above all else. You mastered the basics of accessing the most fundamental sources of knowledge.','["Arcana", "History"]','[]','["Calligrapher''s Supplies"]','{"option_a": {"equipment": ["quarterstaff", "calligraphers_supplies", "history_book", "parchment_8", "robe"], "gold": 8}, "option_b": {"gold": 50}}','["quarterstaff", "calligraphers_supplies", "history_book", "parchment_8", "robe"]',8,'','','Magic Initiate (Wizard)',4);
INSERT INTO races VALUES('human','Human','Versatile and ambitious, humans are the most common race in most D&D worlds.','Medium',30,'{}','{"resourceful": "You gain Heroic Inspiration whenever you finish a Long Rest.", "skillful": "You gain proficiency in one skill of your choice.", "versatile": "You gain an Origin feat of your choice."}','["Common"]','[]',0);
INSERT INTO races VALUES('dwarf','Dwarf','Bold and hardy, dwarves are known as skilled warriors, miners, and workers of stone and metal.','Medium',25,'{}','{"darkvision": "You have Darkvision with a range of 120 feet.", "dwarven_resilience": "You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition.", "dwarven_toughness": "Your Hit Point maximum increases by 1, and it increases by 1 again whenever you gain a level."}','["Common", "Dwarvish"]','[]',1);
