INSERT INTO weapon_masteries VALUES(1,'Cleave','on_hit','If you hit a creature with a melee attack roll using this weapon, you can make a melee attack roll with the weapon against a second creature within 5 feet of the first that is also within your reach. On a hit, the second creature takes the weapon''s damage, but don''t add your ability modifier to that damage unless that modifier is negative. You can make this extra attack only once per turn.',0,NULL,NULL,'weapon_damage_no_modifier','extra_attack_adjacent');
INSERT INTO weapon_masteries VALUES(2,'Graze','on_miss','If your attack roll with this weapon misses a creature, you can deal damage to that creature equal to the ability modifier you used to make the attack roll. This damage is the same type dealt by the weapon, and the damage can be increased only by increasing the ability modifier.',0,NULL,NULL,'ability_modifier','damage_on_miss');
INSERT INTO weapon_masteries VALUES(3,'Nick','on_hit','When you make the extra attack of the Light property, you can make it as part of the Attack action instead of as a Bonus Action. You can make this extra attack only once per turn.',0,NULL,NULL,NULL,'light_attack_as_action');
INSERT INTO weapon_masteries VALUES(4,'Push','on_hit','If you hit a creature with this weapon, you can push the creature up to 10 feet straight away from yourself if it is Large or smaller.',0,NULL,NULL,NULL,'push_10_feet');
INSERT INTO weapon_masteries VALUES(5,'Sap','on_hit','If you hit a creature with this weapon, that creature has Disadvantage on its next attack roll before the start of your next turn.',0,NULL,NULL,NULL,'disadvantage_next_attack');
INSERT INTO weapon_masteries VALUES(6,'Slow','on_hit','If you hit a creature with this weapon and deal damage to it, you can reduce its Speed by 10 feet until the start of your next turn. If the creature is hit more than once by weapons that have this property, the Speed reduction doesn''t exceed 10 feet.',0,NULL,NULL,NULL,'reduce_speed_10');
INSERT INTO weapon_masteries VALUES(7,'Topple','on_hit','If you hit a creature with this weapon, you can force the creature to make a Constitution saving throw (DC 8 plus the ability modifier used to make the attack roll and your Proficiency Bonus). On a failed save, the creature has the Prone condition.',1,'Constitution','8 + ability_modifier + proficiency_bonus',NULL,'prone_on_failed_save');
INSERT INTO weapon_masteries VALUES(8,'Vex','on_hit','If you hit a creature with this weapon and deal damage to the creature, you have Advantage on your next attack roll against that creature before the end of your next turn.',0,NULL,NULL,NULL,'advantage_next_attack');
